import Link from "next/link";

// Statische Anleitung: erklärt jede Funktion des Cockpits in einfachen Worten.
// Warum eine eigene Seite: Jury und Team sehen so ohne Vorwissen, was man wo klicken kann.

const STEPS = [
  {
    title: "1. Szenario wählen",
    text: "Oben links wählst du Modell und Markt (z. B. 5er G60 US). Daneben siehst du, wie viele Kundenstimmen, Funde und Anforderungen die KI ausgewertet hat.",
  },
  {
    title: "2. Rangliste lesen",
    text: "Jede Zeile ist ein Vorschlag der KI. Rang = Reihenfolge nach Punktzahl. Der Balken zeigt den Score (0-100), „linked findings“ die Zahl der Belege dahinter.",
  },
  {
    title: "3. Zeile öffnen",
    text: "Ein Klick auf die Zeile zeigt Beschreibung, Annahmen, die Rechnung hinter dem Score (Waterfall), alle Belege und Webquellen.",
  },
  {
    title: "4. Entscheiden",
    text: "Im Detail kannst du den Vorschlag genehmigen, ablehnen, bearbeiten oder die KI herausfordern (z. B. „Gilt das nur in den USA?“). Jede Entscheidung braucht eine Begründung.",
  },
  {
    title: "5. Audit-Trail prüfen",
    text: "Unter „Audit trail“ steht jede Änderung mit Person, Zeit und Begründung. So bleibt nachvollziehbar, wer was warum entschieden hat.",
  },
];

const EVIDENCE = [
  ["A · strong", "Viele direkte Kundennennungen aus mehreren Quellen. Belastbar."],
  ["B · medium", "Mehrere Hinweise, aber weniger Quellen oder weniger Nennungen."],
  ["C · weak", "Wenige Belege. Vorsichtig behandeln."],
  ["D · assumption", "Annahme oder Trend ohne direkte Kundenstimmen, z. B. für die nächste Fahrzeuggeneration."],
];

const WEIGHTS = [
  ["Customer pain", "Wie stark leiden Kunden unter dem Problem?"],
  ["Reach", "Wie viele Kunden sind betroffen?"],
  ["Satisfaction gap", "Wie weit liegt die Zufriedenheit unter dem Zielwert?"],
  ["Competitive pressure", "Machen Wettbewerber es besser?"],
  ["Future relevance", "Wird das Thema für den Nachfolger wichtiger?"],
  ["Low effort", "Je geringer der Aufwand (S/M/L), desto höher der Score."],
];

const FEATURES = [
  ["Weight controls", "Mit den Reglern änderst du, was dir wichtig ist. „Apply weights“ rechnet die Rangliste neu (das Backend normalisiert die Summe auf 1) und schreibt WEIGHTS_CHANGED in den Audit-Trail. Ohne eigene Begründung nutzt das Cockpit eine Demo-Begründung. „Reset to default“ setzt die Regler zurück, wendet aber noch nichts an."],
  ["Conflicting evidence", "Gelbes Label: Zwei Belege widersprechen sich (z. B. Kunden in den USA sagen etwas anderes als in Europa). Im Detail steht, welche."],
  ["Status", "Proposed (neu), Challenged (hinterfragt), Approved (genehmigt), Rejected (abgelehnt)."],
  ["Overview", "Zusammenfassung: Trichter von Kundenstimmen bis Anforderungen, Top-Vorschläge, Verteilung der Evidenzstufen, Workflow und Warnungen."],
  ["Export CSV", "Lädt die aktuelle Rangliste als Tabelle herunter, z. B. für Excel oder ein Ticket-System."],
];

function Card({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className="rounded-lg border border-slate-200 bg-white p-5 shadow-sm">
      <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">{title}</h2>
      <div className="mt-3">{children}</div>
    </section>
  );
}

function Definitions({ rows }: { rows: string[][] }) {
  return (
    <dl className="grid gap-3 text-sm">
      {rows.map(([term, text]) => (
        <div key={term}>
          <dt className="font-semibold text-[#0b1f3a]">{term}</dt>
          <dd className="text-slate-600">{text}</dd>
        </div>
      ))}
    </dl>
  );
}

export default function GuidePage() {
  return (
    <main className="min-h-screen px-4 py-6 sm:px-6 lg:px-8">
      <div className="mx-auto grid max-w-3xl gap-4">
        <header className="rounded-lg border border-slate-200 bg-white p-5 shadow-sm">
          <p className="text-xs font-semibold uppercase tracking-wide text-slate-500">Signal2Spec</p>
          <h1 className="mt-1 text-2xl font-semibold text-[#0b1f3a]">Anleitung zum PM Cockpit</h1>
          <p className="mt-1 text-sm text-slate-600">
            Die KI schlägt vor, was als Nächstes gebaut werden soll. Du entscheidest, ob das stimmt, und siehst für jeden Vorschlag die Belege.
          </p>
          <Link
            href="/"
            className="mt-4 inline-flex min-h-11 items-center rounded-md bg-blue-600 px-4 text-sm font-semibold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-600 focus:ring-offset-2"
          >
            Zurück zum Cockpit
          </Link>
        </header>

        <Card title="So arbeitest du in 5 Schritten">
          <Definitions rows={STEPS.map((s) => [s.title, s.text])} />
        </Card>
        <Card title="Alle Funktionen">
          <Definitions rows={FEATURES} />
        </Card>
        <Card title="Evidenzstufen (A bis D)">
          <Definitions rows={EVIDENCE} />
        </Card>
        <Card title="Die sechs Gewichte im Score">
          <Definitions rows={WEIGHTS} />
        </Card>
      </div>
    </main>
  );
}

