    >
      {style.label}
    </span>
  );
}

export function ConflictBadge({
  conflictingTitles,
  href,
}: {
  conflictingTitles: string[];
  href?: string;
}) {
  if (conflictingTitles.length === 0) return null;
  const label = "Conflicting evidence";
  const className =
    "inline-flex min-h-7 items-center rounded-full border border-yellow-300 bg-yellow-50 px-3 text-xs font-semibold text-yellow-800";
  if (href) {
    return (
      <a className={`${className} hover:bg-yellow-100`} href={href} title={conflictingTitles.join(", ")}>
        {label}
      </a>
    );
  }
  return (
    <span className={className} title={conflictingTitles.join(", ")}>
      {label}
export function ScoreBar({ score, source }: { score: number; source?: string }) {
  const width = Math.max(0, Math.min(100, score));
  return (
    <div className="min-w-36">
      <div className="flex items-center gap-3">
        <div className="h-2.5 w-28 overflow-hidden rounded-full bg-slate-200">
          <div className="h-full rounded-full bg-blue-600" style={{ width: `${width}%` }} />
        </div>
        <span className="w-11 text-right text-sm font-semibold text-[#0b1f3a]">
          {score.toFixed(1)}
        </span>
      </div>
      {source && <p className="mt-1 text-[11px] text-slate-500">{source}</p>}
    </div>
  );
}
